declare(strict_types=1);
namespace Sexogate;
final class Commerce
{
    private Inventory $inventory;private Cart $cart;private CheckoutPolicy $policy;
    public function __construct(private Database $db,private Config $config){$this->inventory=new Inventory($db,$config);$this->cart=new Cart($db,$config);$this->policy=new CheckoutPolicy($db,$config);}
    private function canonical(mixed $v):mixed
    {if(!is_array($v))return $v;if(array_is_list($v))return array_map(fn($x)=>$this->canonical($x),$v);ksort($v,SORT_STRING);foreach($v as &$x)$x=$this->canonical($x);return $v;}
    private function fingerprint(mixed $v):string{return hash_hmac('sha256','php:quote:v1:'.$this->config->json($this->canonical($v)),$this->config->get('secret'));}
    private function selection(array $input):array
    {$coupon=$input['couponCode']??null;RuleViolation::ensure($coupon===null||is_string($coupon),'INVALID_CHECKOUT','Kupon alanını kontrol edin.',400);$coupon=$coupon===null?null:mb_strtoupper(trim($coupon),'UTF-8');$s=['country'=>$input['country']??'TR','currency'=>$input['currency']??'TRY','locale'=>$input['locale']??'tr','couponCode'=>$coupon===''?null:$coupon];foreach($s as $v)RuleViolation::ensure($v===null||is_string($v),'INVALID_CHECKOUT','Alışveriş seçimlerini kontrol edin.',400);return $s;}
    private function evaluate(array $cart,array $selection,bool $locked):array
    {
        $country=$this->policy->country($selection['country'],$selection['currency']);
        if($locked){
            $this->inventory->definition('bundle-definition');$this->inventory->definition('fulfillment-definition');
            $links=$this->db->all('SELECT id,product_id FROM variants WHERE id IN(SELECT variant_id FROM cart_items WHERE cart_id=? UNION SELECT component_variant_id FROM bundle_components bc JOIN cart_items ci ON ci.variant_id=bc.bundle_variant_id WHERE ci.cart_id=?) ORDER BY id',[$cart['id'],$cart['id']]);
            if($links){$products=array_values(array_unique(array_column($links,'product_id')));sort($products,SORT_STRING);$ids=array_column($links,'id');$this->db->all('SELECT id FROM products WHERE id IN('.Database::slots($products).') ORDER BY id FOR SHARE',$products);$this->db->all('SELECT id FROM variants WHERE id IN('.Database::slots($ids).') ORDER BY id FOR SHARE',$ids);}
        }
        $items=$this->db->all('SELECT v.*,ci.quantity,p.name product_name,p.name_en product_name_en,p.description,p.description_en,p.image,p.material,p.warnings,p.care,p.manufacturer,p.translations,p.status product_status,p.fixture FROM cart_items ci JOIN variants v ON v.id=ci.variant_id JOIN products p ON p.id=v.product_id WHERE ci.cart_id=? AND ci.selected=true ORDER BY v.id'.($locked?' FOR SHARE':''),[$cart['id']]);RuleViolation::ensure($items,'EMPTY_CART','Sepetinize ürün ekleyin.',400);
        foreach($items as &$item){
            RuleViolation::ensure((bool)$item['active']&&$item['product_status']==='published','PRODUCT_UNAVAILABLE','Sepetteki ürün artık satışa açık değil.');RuleViolation::ensure(!(bool)$item['fixture']||$this->config->local(),'FIXTURE_NOT_ALLOWED','Örnek ürünle gerçek satış yapılamaz.',503);
            $price=$this->db->one('SELECT variant_id,currency,amount_minor,valid_from,valid_until FROM variant_prices WHERE variant_id=? AND currency=? AND valid_from<=CURRENT_TIMESTAMP(3) AND(valid_until IS NULL OR valid_until>CURRENT_TIMESTAMP(3)) FOR SHARE',[$item['id'],$selection['currency']]);RuleViolation::ensure($price,'PRICE_NOT_CONFIGURED','Bu para birimi için fiyat listesi yok.');$item['price_minor']=Money::amount($price['amount_minor']);$item['price_source']=$price;$item['tax_rule']=$this->policy->tax($selection['country'],$item['tax_class']);$this->policy->eligible($item['id'],$selection['country']);
            foreach($this->db->all('SELECT component_variant_id FROM bundle_components WHERE bundle_variant_id=?',[$item['id']]) as $part)$this->policy->eligible($part['component_variant_id'],$selection['country']);
            $en=$selection['locale']==='en';$item['display_name']=$en?$item['product_name_en']:$item['product_name'];$item['variant_display']=$en?$item['name_en']:$item['name'];$item['display_description']=$en?$item['description_en']:$item['description'];$translated=json_decode($item['translations'],true);$item['display_warnings']=$en?($translated['en']['warnings']??''):$item['warnings'];$item['display_care']=$en?($translated['en']['care']??''):$item['care'];
        }unset($item);
        $plan=$this->inventory->plan($items,$country,$locked);$taxInputs=array_map(fn($r)=>['grossMinor'=>Money::multiply($r['price_minor'],(int)$r['quantity']),'rateBps'=>$r['tax_rule']['rateBps']],$items);$subtotal=Money::sum(array_column($taxInputs,'grossMinor'));$cost=$plan['handlingMinor'];foreach($plan['lines'] as $line)$cost=Money::sum([$cost,Money::multiply($line['unitCostMinor'],$line['quantity'])]);
        $discount=0;$coupon=null;
        if($selection['couponCode']){
            $coupon=$this->db->one('SELECT * FROM coupons WHERE UPPER(code)=UPPER(?)'.($locked?' FOR UPDATE':''),[$selection['couponCode']]);RuleViolation::ensure($coupon&&(bool)$coupon['active']&&strtotime($coupon['expires_at'].' UTC')>time(),'COUPON_INVALID','Kupon geçerli değil.');RuleViolation::ensure($subtotal>=(int)$coupon['minimum_minor'],'COUPON_MINIMUM','Sepet kuponun alt sınırını karşılamıyor.');
            $count=(int)$this->db->one("SELECT COUNT(*) n FROM coupon_usage u JOIN orders o ON o.id=u.order_id WHERE u.coupon_id=? AND(u.status='consumed' OR(u.status='reserved' AND o.status='awaiting_payment' AND o.expires_at>CURRENT_TIMESTAMP(3)))",[$coupon['id']])['n'];RuleViolation::ensure($count<(int)$coupon['max_uses'],'COUPON_LIMIT','Kupon kullanım sınırına ulaştı.');$discount=Money::basisPoints($subtotal,(int)$coupon['discount_bps']);
        }
        $taxes=Money::mixed($taxInputs,$discount);if($coupon)RuleViolation::ensure($taxes['grossAfterDiscountMinor']-$taxes['goodsTaxMinor']-$cost>=(int)$coupon['minimum_contribution_minor'],'COUPON_MARGIN','Kupon bu sepet için uygulanamıyor.');
        $shippingTax=$this->policy->shippingTax($country);$shipping=$plan['shippingMinor'];$totals=['subtotalMinor'=>$subtotal,'discountMinor'=>$discount,'shippingMinor'=>$shipping,'goodsTaxMinor'=>$taxes['goodsTaxMinor'],'shippingTaxMinor'=>Money::inclusiveTax($shipping,$shippingTax['rateBps']),'totalMinor'=>Money::sum([$subtotal-$discount,$shipping])];$totals['taxMinor']=$totals['goodsTaxMinor']+$totals['shippingTaxMinor'];
        $agreements=$this->policy->agreements($selection['locale']);$profile=$this->policy->profile($selection['country']);
        $binding=['cartId'=>$cart['id'],'selection'=>$selection,'items'=>$items,'lines'=>$plan['lines'],'groups'=>$plan['groups'],'totals'=>$totals,'profile'=>$profile,'deliveryTerm'=>$country['delivery_term'],'shippingTax'=>$shippingTax,'coupon'=>$coupon,'agreements'=>array_map(fn($a)=>array_intersect_key($a,array_flip(['id','kind','version','body_hash'])),$agreements)];
        return compact('country','items','plan','taxes','cost','coupon','shippingTax','totals','agreements','profile')+['binding'=>$this->fingerprint($binding)];
    }
    public function quote(string $token,array $input,?string $caller=null):array
    {
        $selection=$this->selection($input);return $this->db->transaction(function()use($token,$selection,$caller){$cart=$this->cart->row($token,$caller,false,false);$p=$this->evaluate($cart,$selection,false);$claims=['version'=>1,'cartId'=>$cart['id'],'cartHash'=>Cart::token($token),'selectionHash'=>$this->fingerprint($selection),'evaluationHash'=>$p['binding'],'issuedAt'=>time(),'expiresAt'=>time()+300];$payload=rtrim(strtr(base64_encode($this->config->json($claims)),'+/','-_'),'=');
            return $p['totals']+['currency'=>$selection['currency'],'quoteToken'=>$payload.'.'.hash_hmac('sha256','quote:'.$payload,$this->config->get('secret')),'expiresAt'=>gmdate('c',$claims['expiresAt']),'deliveryTerm'=>$p['country']['delivery_term'],'profile'=>$p['profile'],'packages'=>array_map(fn($g)=>array_intersect_key($g,array_flip(['source','shippingMinor','minDays','maxDays'])),$p['plan']['groups'])];
        },true);
    }
    private function verifyQuote(string $value,string $token,array $cart,array $selection,array $pricing):array
    {
        RuleViolation::ensure(strlen($value)>0&&strlen($value)<=2048,'CHECKOUT_QUOTE_REQUIRED','Güncel sipariş özetini inceleyin.');$parts=explode('.',$value);RuleViolation::ensure(count($parts)===2&&hash_equals(hash_hmac('sha256','quote:'.$parts[0],$this->config->get('secret')),$parts[1]),'CHECKOUT_QUOTE_INVALID','Sipariş toplamı doğrulanamadı.');
        $claims=json_decode(base64_decode(strtr($parts[0],'-_','+/'),true)?:'',true);RuleViolation::ensure(is_array($claims)&&($claims['version']??null)===1&&($claims['expiresAt']??0)>time()&&($claims['issuedAt']??PHP_INT_MAX)<=time()&&$claims['expiresAt']-$claims['issuedAt']===300,'CHECKOUT_QUOTE_EXPIRED','Sipariş özetinin süresi doldu. Yenileyin.');
        RuleViolation::ensure($claims['cartId']===$cart['id']&&hash_equals($claims['cartHash'],Cart::token($token))&&hash_equals($claims['selectionHash'],$this->fingerprint($selection))&&hash_equals($claims['evaluationHash'],$pricing['binding']),'CHECKOUT_QUOTE_CHANGED','Sipariş tutarı veya koşulları değişti. Güncel özeti inceleyin.');return $claims;
    }
    public function checkout(string $token,array $input,?string $caller=null):array
    {
        $this->policy->live();if($this->config->get('payment_provider')==='stripe')new \Sexogate\Providers\StripeProvider($this->config);RuleViolation::ensure(is_string($input['email']??null)&&strlen($input['email'])<=254&&filter_var($input['email'],FILTER_VALIDATE_EMAIL),'INVALID_EMAIL','E-posta adresini kontrol edin.',400);RuleViolation::ensure(($input['privacyAccepted']??false)===true&&($input['termsAccepted']??false)===true,'AGREEMENTS_REQUIRED','Gerekli metinleri inceleyip onaylayın.',400);
        $key=$input['idempotencyKey']??'';RuleViolation::ensure(is_string($key)&&strlen($key)>=16&&strlen($key)<=128,'IDEMPOTENCY_REQUIRED','İşlem anahtarı geçersiz.',400);$semantic=$input;unset($semantic['quoteToken']);$hash=hash('sha256',$this->config->json($this->canonical($semantic)));$track=hash_hmac('sha256','tracking:'.$token.':'.$key,$this->config->get('secret'));$selection=$this->selection($input);
        $order=$this->db->transaction(function()use($token,$input,$caller,$key,$hash,$track,$selection){
            $cart=$this->cart->row($token,$caller,true);if($caller!==null&&$cart['user_id']===null){$this->db->execute('UPDATE carts SET user_id=? WHERE id=?',[$caller,$cart['id']]);$cart['user_id']=$caller;}$old=$this->db->one('SELECT * FROM orders WHERE cart_id=? AND idempotency_key=?',[$cart['id'],$key]);if($old){RuleViolation::ensure($old['user_id']===null||$old['user_id']===$caller,'ORDER_NOT_FOUND','Sipariş bulunamadı.',404);RuleViolation::ensure(hash_equals($old['request_hash'],$hash),'IDEMPOTENCY_CONFLICT','Aynı işlem anahtarı farklı bilgilerle kullanılamaz.');return $old;}
            RuleViolation::ensure(!$this->db->one("SELECT id FROM orders WHERE cart_id=? AND status='awaiting_payment' AND expires_at>CURRENT_TIMESTAMP(3)",[$cart['id']]),'PAYMENT_ALREADY_PENDING','Bu sepet için devam eden ödeme var.');
            $p=$this->evaluate($cart,$selection,true);$claims=$this->verifyQuote($input['quoteToken']??'',$token,$cart,$selection,$p);$address=$this->policy->address($input,$p['profile']);$billing=$address;RuleViolation::ensure(!isset($input['sameBilling'])||is_bool($input['sameBilling']),'INVALID_BILLING','Fatura adresi seçimini kontrol edin.',400);if(($input['sameBilling']??true)===false){$billingInput=['phone'=>$input['phone']??''];foreach($p['profile']['fields'] as $field)if($field['id']!=='phone')$billingInput[$field['id']]=$input['billing'.ucfirst($field['id'])]??'';RuleViolation::ensure(($input['billingCountry']??$selection['country'])===$selection['country'],'BILLING_COUNTRY_UNSUPPORTED','Bu teslimatta fatura adresi aynı ülke içinde olmalıdır.',400);$billing=$this->policy->address($billingInput,$p['profile']);}$id=Database::id();$expires=gmdate('Y-m-d H:i:s',time()+($this->config->get('payment_provider')==='stripe'?1800:900));$t=$p['totals'];$snapshot=['billingAddress'=>$billing,'checkoutQuote'=>$claims,'productTaxRules'=>array_column($p['items'],'tax_rule'),'shippingTaxRule'=>$p['shippingTax'],'priceSource'=>'fixed-price-list','deliveryTerm'=>$p['country']['delivery_term'],'taxPriceBasis'=>'inclusive','totals'=>$t];
            $provider=$this->config->get('payment_provider');RuleViolation::ensure(in_array($provider,['test','stripe'],true),'PAYMENT_NOT_CONFIGURED','Gerçek ödeme bağlantısının kabulü ve kurulumu tamamlanmadı.',503);RuleViolation::ensure($provider!=='test'||$this->config->local(),'TEST_PROVIDER_DISABLED','Test ödemesi kapalı.',503);
            $this->db->execute('INSERT INTO orders(id,cart_id,user_id,idempotency_key,request_hash,tracking_hash,currency,subtotal_minor,discount_minor,shipping_minor,tax_minor,total_minor,cost_minor,email,address,locale,snapshot,address_profile_id,expires_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[$id,$cart['id'],$cart['user_id'],$key,$hash,hash('sha256',$track),$selection['currency'],$t['subtotalMinor'],$t['discountMinor'],$t['shippingMinor'],$t['taxMinor'],$t['totalMinor'],$p['cost'],$input['email'],$this->config->json($address),$selection['locale'],$this->config->json($snapshot),$p['profile']['id'],$expires]);
            $groups=$this->inventory->reserve($id,$expires,$p['plan']);
            foreach($p['items'] as $i=>$item){$line=$p['plan']['lines'][$i];$allocation=$p['taxes']['lines'][$i];$itemSnapshot=['name'=>$item['display_name'],'variantName'=>$item['variant_display'],'description'=>$item['display_description'],'warnings'=>$item['display_warnings'],'care'=>$item['display_care'],'image'=>$item['image'],'material'=>$item['material'],'manufacturer'=>$item['manufacturer'],'taxRule'=>$item['tax_rule'],'bundleComponents'=>$line['components'],'fulfillmentSource'=>$line['source']];$this->db->execute('INSERT INTO order_items(order_id,variant_id,name,sku,quantity,unit_minor,cost_minor,tax_minor,discount_minor,snapshot,fulfillment_source,fulfillment_group_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)',[$id,$item['id'],$item['display_name'],$item['sku'],$item['quantity'],$item['price_minor'],$line['unitCostMinor'],$allocation['taxMinor'],$allocation['discountMinor'],$this->config->json($itemSnapshot),$line['source'],$groups[$line['groupKey']]]);}
            if($p['coupon'])$this->db->execute('INSERT INTO coupon_usage(coupon_id,order_id) VALUES(?,?)',[$p['coupon']['id'],$id]);$this->db->execute('INSERT INTO payments(order_id,provider,amount_minor,currency) VALUES(?,?,?,?)',[$id,$provider,$t['totalMinor'],$selection['currency']]);
            foreach($p['agreements'] as $a)$this->db->execute('INSERT INTO order_agreements(order_id,document_id,kind,version,locale,title,body,body_hash,accepted_at) VALUES(?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP(3))',[$id,$a['id'],$a['kind'],$a['version'],$a['locale'],$a['title'],$a['body'],$a['body_hash']]);
            $this->history($id,'order','awaiting_payment');$this->enqueue('reservation.expire',['orderId'=>$id],'reservation:'.$id,$expires);return $this->db->one('SELECT * FROM orders WHERE id=?',[$id]);
        });
        return ['orderId'=>$order['id'],'number'=>$order['number'],'totalMinor'=>(int)$order['total_minor'],'currency'=>$order['currency'],'trackingToken'=>$track,'paymentUrl'=>$this->config->path(($this->config->get('payment_provider')==='stripe'?'/odeme/stripe?order=':'/odeme/test?order=').rawurlencode($order['id']).'&token='.rawurlencode($track))];
    }
    public function order(string $id,?string $tracking=null,?string $user=null):?array
    {
        $r=$this->db->one('SELECT id,number,status,payment_status,fulfillment_status,currency,subtotal_minor,discount_minor,shipping_minor,tax_minor,total_minor,created_at FROM orders WHERE id=? AND((? IS NOT NULL AND tracking_hash=?) OR(? IS NOT NULL AND user_id=?))',[$id,$tracking,$tracking===null?null:hash('sha256',$tracking),$user,$user]);if(!$r)return null;
        $r['items']=$this->db->all('SELECT name,sku,quantity,unit_minor,variant_id,fulfillment_source FROM order_items WHERE order_id=? ORDER BY id',[$id]);$r['packages']=array_map(fn($p)=>array_intersect_key(json_decode($p['snapshot'],true),array_flip(['number','source','shippingMinor','minDays','maxDays','carrier'])),$this->db->all('SELECT snapshot FROM order_fulfillment_groups WHERE order_id=? ORDER BY id',[$id]));foreach(['subtotal_minor','discount_minor','shipping_minor','tax_minor','total_minor'] as $key)$r[$key]=(int)$r[$key];return $r;
    }
    public function testEvent(string $id,string $tracking,string $outcome):array
    {
        RuleViolation::ensure($this->config->local()&&$this->config->get('payment_provider')==='test','TEST_PROVIDER_DISABLED','Test ödeme sağlayıcısı kapalı.',503);$o=$this->order($id,$tracking);RuleViolation::ensure($o,'ORDER_NOT_FOUND','Sipariş bulunamadı.',404);RuleViolation::ensure(in_array($outcome,['succeeded','failed'],true),'INVALID_OUTCOME','Ödeme sonucu geçersiz.',400);
        $raw=$this->config->json(['id'=>'test-'.Database::id(),'orderId'=>$id,'amountMinor'=>$o['total_minor'],'currency'=>$o['currency'],'status'=>$outcome,'timestamp'=>time()]);return ['raw'=>$raw,'signature'=>hash_hmac('sha256',$raw,$this->config->get('secret'))];
    }
    public function handleTest(string $raw,string $signature):array
    {
        RuleViolation::ensure($this->config->local()&&$this->config->get('payment_provider')==='test','TEST_PROVIDER_DISABLED','Test ödeme sağlayıcısı kapalı.',503);RuleViolation::ensure(strlen($raw)<=32768&&hash_equals(hash_hmac('sha256',$raw,$this->config->get('secret')),$signature),'INVALID_SIGNATURE','Ödeme bildirimi doğrulanamadı.',401);
        try{$e=json_decode($raw,true,32,JSON_THROW_ON_ERROR);}catch(\Throwable){throw new RuleViolation('INVALID_EVENT','Ödeme bildirimi geçersiz.',400);}RuleViolation::ensure(is_array($e)&&is_string($e['id']??null)&&strlen($e['id'])>=8&&strlen($e['id'])<=200&&is_string($e['orderId']??null)&&is_int($e['amountMinor']??null)&&is_int($e['timestamp']??null)&&abs(time()-$e['timestamp'])<=300&&in_array($e['status']??null,['succeeded','failed'],true),'INVALID_EVENT','Ödeme bildirimi geçersiz.',400);Money::amount($e['amountMinor']);return $this->settle($e,'test',hash('sha256',$raw));
    }
    public function settle(array $e,string $provider,?string $hash=null):array
    {
        $hash??=hash('sha256',$this->config->json($e));return $this->db->transaction(function()use($e,$provider,$hash){
            $this->inventory->definition('fulfillment-definition');$o=$this->db->one('SELECT * FROM orders WHERE id=? FOR UPDATE',[$e['orderId']]);RuleViolation::ensure($o,'ORDER_NOT_FOUND','Ödeme siparişi bulunamadı.',404);$p=$this->db->one('SELECT * FROM payments WHERE order_id=? FOR UPDATE',[$o['id']]);
            RuleViolation::ensure($p&&$p['provider']===$provider,'PROVIDER_MISMATCH','Ödeme sağlayıcısı eşleşmiyor.');if($provider!=='test')RuleViolation::ensure(!empty($e['providerReference'])&&($p['provider_reference']===null||$p['provider_reference']===$e['providerReference']),'PAYMENT_REFERENCE_MISMATCH','Ödeme oturumu eşleşmiyor.');RuleViolation::ensure((int)$p['amount_minor']===$e['amountMinor']&&$p['currency']===$e['currency'],'PAYMENT_MISMATCH','Ödeme tutarı veya para birimi eşleşmiyor.');
            $old=$this->db->one('SELECT payload_hash FROM payment_events WHERE id=?',[$e['id']]);if($old){RuleViolation::ensure(hash_equals($old['payload_hash'],$hash),'EVENT_CONFLICT','Ödeme olayı farklı içerikle tekrarlandı.');return ['duplicate'=>true];}$this->db->execute('INSERT INTO payment_events(id,payment_id,payload_hash,status) VALUES(?,?,?,?)',[$e['id'],$p['id'],$hash,$e['status']]);if(in_array($p['status'],['succeeded','partially_refunded','refunded'],true))return ['duplicate'=>false];
            $reservations=$this->db->all('SELECT * FROM reservations WHERE order_id=? ORDER BY variant_id FOR UPDATE',[$o['id']]);$ids=array_column($reservations,'variant_id');$balances=$ids?$this->db->all("SELECT variant_id,on_hand FROM inventory_balance WHERE warehouse_id='main' AND variant_id IN(".Database::slots($ids).') ORDER BY variant_id FOR UPDATE',$ids):[];$map=array_column($balances,'on_hand','variant_id');$supplier=$this->supplierState($o);
            if($e['status']==='failed'){$this->release($o['id'],'released');$this->db->execute("UPDATE payments SET status='failed',updated_at=CURRENT_TIMESTAMP(3) WHERE id=?",[$p['id']]);$this->db->execute("UPDATE orders SET status='cancelled',payment_status='failed',updated_at=CURRENT_TIMESTAMP(3) WHERE id=?",[$o['id']]);$this->history($o['id'],'payment','failed',[],$p['status']);return ['duplicate'=>false];}
            $late=$o['status']!=='awaiting_payment'||strtotime($o['expires_at'].' UTC')<=time()||(!$reservations&&!$supplier['held']);$missing=false;
            foreach($reservations as $r){$late=$late||$r['status']!=='active'||strtotime($r['expires_at'].' UTC')<=time();$missing=$missing||(int)($map[$r['variant_id']]??0)<(int)$r['quantity']||!$this->inventory->lotsValid($r);}
            $this->db->execute("UPDATE payments SET status='succeeded',provider_reference=COALESCE(provider_reference,?),updated_at=CURRENT_TIMESTAMP(3) WHERE id=?",[$e['providerReference']??null,$p['id']]);
            if($late||$missing||!$supplier['valid']){$this->release($o['id'],'released');$this->db->execute("UPDATE order_fulfillment_groups SET status='exception',updated_at=CURRENT_TIMESTAMP(3) WHERE order_id=?",[$o['id']]);$this->db->execute("UPDATE orders SET status='payment_exception',payment_status='succeeded',updated_at=CURRENT_TIMESTAMP(3) WHERE id=?",[$o['id']]);$this->history($o['id'],'payment','payment_exception',['reason'=>$late?'reservation_expired':(!$supplier['valid']?'supplier_unavailable':'stock_or_lot_missing')],$o['status']);$this->enqueue('payment.exception',['orderId'=>$o['id']],'exception:'.$o['id']);return ['duplicate'=>false];}
            foreach($reservations as $r)$this->inventory->consume($r);$this->db->execute("UPDATE reservations SET status='consumed' WHERE order_id=? AND status='active'",[$o['id']]);$this->db->execute("UPDATE supplier_reservations SET status='allocated' WHERE order_id=? AND status='active'",[$o['id']]);$this->db->execute("UPDATE order_fulfillment_groups SET status='ready',updated_at=CURRENT_TIMESTAMP(3) WHERE order_id=? AND status='awaiting_payment'",[$o['id']]);$this->db->execute("UPDATE orders SET status='confirmed',payment_status='succeeded',updated_at=CURRENT_TIMESTAMP(3) WHERE id=?",[$o['id']]);
            $usage=$this->db->one("SELECT coupon_id FROM coupon_usage WHERE order_id=? AND status='reserved' FOR UPDATE",[$o['id']]);if($usage){$this->db->execute("UPDATE coupon_usage SET status='consumed' WHERE order_id=?",[$o['id']]);$this->db->execute('UPDATE coupons SET used_count=used_count+1 WHERE id=?',[$usage['coupon_id']]);}$this->db->execute('DELETE ci FROM cart_items ci JOIN order_items oi ON oi.variant_id=ci.variant_id AND oi.order_id=? WHERE ci.cart_id=? AND ci.quantity<=oi.quantity',[$o['id'],$o['cart_id']]);$this->db->execute('UPDATE cart_items ci JOIN order_items oi ON oi.variant_id=ci.variant_id AND oi.order_id=? SET ci.quantity=ci.quantity-oi.quantity WHERE ci.cart_id=? AND ci.quantity>oi.quantity',[$o['id'],$o['cart_id']]);$this->db->execute('UPDATE cart_undo SET consumed_at=COALESCE(consumed_at,CURRENT_TIMESTAMP(3)) WHERE cart_id=?',[$o['cart_id']]);$this->history($o['id'],'payment','succeeded',[],$p['status']);$this->enqueue('order.confirmation',['orderId'=>$o['id']],'confirmation:'.$o['id']);return ['duplicate'=>false];
        });
    }
    private function supplierState(array $order):array
    {
        $held=$this->db->all('SELECT * FROM supplier_reservations WHERE order_id=? ORDER BY offer_id FOR UPDATE',[$order['id']]);if(!$held)return ['held'=>[],'valid'=>true];$ids=array_column($held,'offer_id');$this->db->all('SELECT id FROM supplier_offers WHERE id IN('.Database::slots($ids).') ORDER BY id FOR UPDATE',$ids);$address=json_decode($order['address'],true);$rows=$this->db->all('SELECT * FROM supplier_offer_availability WHERE id IN('.Database::slots($ids).') AND country=? AND currency=? AND(fixture=false OR ?=true)',array_merge($ids,[$address['country'],$order['currency'],$this->config->local()?1:0]));$valid=true;
        foreach($held as $r){$offer=null;foreach($rows as $row)if($row['id']===$r['offer_id'])$offer=$row;$valid=$valid&&$r['status']==='active'&&strtotime($r['expires_at'].' UTC')>time()&&$offer!==null&&((int)$offer['reported_quantity']-(int)$offer['safety_stock'])>=(int)$r['quantity'];}
        foreach($rows as $row){$sum=(int)$this->db->one("SELECT COALESCE(SUM(quantity),0) n FROM supplier_reservations WHERE offer_id=? AND(status='allocated' OR(status='active' AND expires_at>CURRENT_TIMESTAMP(3)))",[$row['id']])['n'];if((int)$row['reported_quantity']-(int)$row['safety_stock']<$sum)$valid=false;}return ['held'=>$held,'valid'=>$valid];
    }
    private function release(string $id,string $status):void
    {$this->db->execute("UPDATE reservations SET status=? WHERE order_id=? AND status='active'",[$status,$id]);$this->db->execute("UPDATE supplier_reservations SET status=? WHERE order_id=? AND status='active'",[$status,$id]);$this->db->execute("UPDATE order_fulfillment_groups SET status='cancelled',updated_at=CURRENT_TIMESTAMP(3) WHERE order_id=? AND status='awaiting_payment'",[$id]);$this->db->execute("UPDATE coupon_usage SET status='released' WHERE order_id=? AND status='reserved'",[$id]);}
    public function expire():int
    {return $this->db->transaction(function(){$orders=$this->db->all("SELECT id FROM orders WHERE status='awaiting_payment' AND expires_at<=CURRENT_TIMESTAMP(3) ORDER BY id FOR UPDATE SKIP LOCKED");foreach($orders as $r){$this->release($r['id'],'expired');$this->db->execute("UPDATE orders SET status='cancelled',updated_at=CURRENT_TIMESTAMP(3) WHERE id=?",[$r['id']]);$this->history($r['id'],'order','cancelled',['reason'=>'reservation_expired'],'awaiting_payment');}return count($orders);});}
    public function enqueue(string $type,array $payload,string $key,?string $available=null):void
    {$this->db->execute('INSERT INTO jobs(id,type,payload,dedupe_key,available_at) VALUES(?,?,?,?,COALESCE(?,CURRENT_TIMESTAMP(3))) ON DUPLICATE KEY UPDATE dedupe_key=dedupe_key',[Database::id(),$type,$this->config->json($payload),$key,$available]);}
    private function history(string $id,string $type,string $to,array $details=[],?string $from=null):void
    {$this->db->execute('INSERT INTO order_history(order_id,type,from_status,to_status,details) VALUES(?,?,?,?,?)',[$id,$type,$from,$to,$this->config->json($details)]);}
}
